/* ------------------------------------------------------------------ uploads (photos for products and pages) */
function admin_upload(): void {
    if (!is_post() || empty($_FILES['file']) || $_FILES['file']['error'] !== UPLOAD_ERR_OK) json_out(['error' => 'Upload failed.'], 400);
    $f = $_FILES['file'];
    if ($f['size'] > 8 * 1024 * 1024) json_out(['error' => 'That file is over 8 MB.'], 400);
    $info = @getimagesize($f['tmp_name']);
    $ext = ['image/jpeg' => 'jpg', 'image/png' => 'png', 'image/webp' => 'webp'][$info['mime'] ?? ''] ?? null;
    if (!$ext) json_out(['error' => 'Use a JPG, PNG or WebP image.'], 400);
    $dir = ($_POST['kind'] ?? '') === 'page' ? 'uploads/pages' : 'uploads/products';
    if (!is_dir(ROOT . '/' . $dir)) mkdir(ROOT . '/' . $dir, 0775, true);
    $name = slugify(pathinfo($f['name'], PATHINFO_FILENAME)) . '-' . substr(bin2hex(random_bytes(4)), 0, 6) . '.' . $ext;
    move_uploaded_file($f['tmp_name'], ROOT . "/$dir/$name");
    json_out(['path' => "$dir/$name", 'url' => "/$dir/$name"]);
}

/* ------------------------------------------------------------------ import / export */
const EXPORT_COLS = ['handle', 'title', 'game', 'section', 'subsection', 'set_name', 'set_url', 'series', 'language', 'card_name', 'card_number', 'rarity', 'card_type', 'variant', 'sku',
                     'price_usd', 'compare_usd', 'moq', 'step', 'breaks', 'in_stock', 'published', 'seo_index', 'featured', 'also_on', 'image_url', 'alt_text', 'description', 'seo_title', 'meta_desc', 'weight_kg'];
function admin_export(): never {
    header('Content-Type: text/csv; charset=utf-8');
    header('Content-Disposition: attachment; filename="toramori-products-' . date('Y-m-d') . '.csv"');
    $out = fopen('php://output', 'w');
    fwrite($out, "\xEF\xBB\xBF");
    fputcsv($out, EXPORT_COLS);
    $st = q('SELECT ' . implode(',', EXPORT_COLS) . ' FROM products ORDER BY id');
    while ($r = $st->fetch()) fputcsv($out, array_map(fn($v) => $v ?? '', $r));
    exit;
}
function guess_game(string $title, string $type, string $vendor): string {
    $t = mb_strtolower("$title $type $vendor");
    foreach (['Lorcana' => 'lorcana', 'Riftbound' => 'riftbound|league of legends', 'One Piece' => 'one piece', 'Magic: The Gathering' => 'magic: the gathering|magic the gathering', 'Dragon Ball' => 'dragon ball',
              'Gundam' => 'gundam', 'Naruto' => 'naruto|boruto', 'Yu-Gi-Oh!' => 'yu-gi-oh', 'Digimon' => 'digimon', 'Star Wars' => 'star wars',
              'PokÃ©mon' => 'pok[eÃ©]mon|pikachu|charizard|scarlet & violet|sword & shield|mega evolution|\bex\b|vstar|vmax',
              'Sports' => 'topps|panini|\bafl\b|\bnrl\b|\bnba\b|\bnfl\b|soccer|football|basketball|baseball|formula 1'] as $g => $rx)
        if (preg_match("/$rx/u", $t)) return $g;
    return 'Other collectibles';
}
function guess_section(string $title, string $type): string {
    $t = mb_strtolower("$title $type");
    if (preg_match('/\bpsa \d|\bbgs \d|\bcgc \d|graded card/', $t) && !preg_match('/sleeve|bumper|storage/', $t)) return 'PSA Graded Cards';
    if (preg_match('/^(singles|trading card|jumbo)/', mb_strtolower($type))) return 'Single Cards';
    if (preg_match('/sleeve|top ?loader|binder|portfolio|deck box|playmat|mag-lock|bumper|storage case/', $t)) return 'Accessories';
    if (preg_match('/\bcase\b/', $t) && preg_match('/booster box|elite trainer|\d+ ?ct/', $t)) return 'Booster Box Cases';
    if (str_contains($t, 'elite trainer')) return 'Elite Trainer Boxes';
    if (preg_match('/booster box|hobby box|blaster box|display/', $t)) return 'Booster Boxes';
    if (preg_match('/booster pack|\bpack\b/', $t)) return 'Booster Packs';
    return 'Premium & Special Sets';
}
function admin_import(): void {
    $report = null;
    if (is_post() && !empty($_FILES['csv']) && $_FILES['csv']['error'] === UPLOAD_ERR_OK) {
        @set_time_limit(600);
        $fh = fopen($_FILES['csv']['tmp_name'], 'r');
        $head = fgetcsv($fh);
        if ($head) $head[0] = preg_replace('/^\xEF\xBB\xBF/', '', $head[0]);
        $cols = array_flip(array_map('trim', $head ?: []));
        $mode = isset($cols['price_usd']) ? 'toramori' : (isset($cols['product_url']) && isset($cols['handle']) ? 'cardbot' : null);
        $report = ['mode' => $mode, 'updated' => 0, 'created' => 0, 'skipped' => 0, 'new' => []];
        if (!$mode) { $report['error'] = 'This file has neither the Toramori export columns nor the Card Bot columns.'; }
        else {
            $rate = (float)(rates()['AUD'] ?? 1.53);
            db()->beginTransaction();
            while (($row = fgetcsv($fh)) !== false) {
                $r = []; foreach ($cols as $k => $i) $r[$k] = $row[$i] ?? '';
                if ($mode === 'toramori') {
                    $handle = slugify($r['handle'] ?? '');
                    if ($handle === '' || ($r['title'] ?? '') === '') { $report['skipped']++; continue; }
                    $vals = [];
                    foreach (EXPORT_COLS as $c) if (array_key_exists($c, $r)) $vals[$c] = in_array($c, ['price_usd', 'compare_usd', 'moq', 'step', 'weight_kg'], true) ? (is_numeric($r[$c]) ? $r[$c] + 0 : null) : ($c === 'breaks' ? ($r[$c] !== '' ? $r[$c] : null) : $r[$c]);
                    $vals['handle'] = $handle;
                    $ex = one('SELECT id FROM products WHERE handle = ?', [$handle]);
                    if (!isset($vals['section_url']) && isset($vals['section'])) $vals['section_url'] = section_url_for($vals['game'] ?? 'PokÃ©mon', $vals['section']);
                    if ($ex) { q('UPDATE products SET ' . implode(', ', array_map(fn($k) => "$k = ?", array_keys($vals))) . ", updated_at = datetime('now') WHERE id = ?", [...array_values($vals), $ex['id']]); $id = (int)$ex['id']; $report['updated']++; }
                    else { q('INSERT INTO products(' . implode(',', array_keys($vals)) . ", source) VALUES(" . implode(',', array_fill(0, count($vals), '?')) . ", 'import')", array_values($vals)); $id = (int)db()->lastInsertId(); $report['created']++; }
                    sync_product_paths($id);
                } else {
                    $sid = (string)($r['id'] ?? '');
                    $price = is_numeric($r['price'] ?? null) ? round((float)$r['price'] / $rate, 2) : null;
                    $stock = in_array(strtolower((string)($r['available'] ?? '')), ['true', '1', 'yes'], true) ? 1 : 0;
                    $ex = $sid !== '' ? one("SELECT id, source_price FROM products WHERE source = 'cardbot' AND source_id = ?", [$sid]) : null;
                    if ($ex) {
                        q("UPDATE products SET in_stock = ?, source_price = ?, price_usd = CASE WHEN moq IS NULL AND breaks IS NULL THEN ? ELSE price_usd END, image_url = CASE WHEN image_local = '' AND ? != '' THEN ? ELSE image_url END, updated_at = datetime('now') WHERE id = ?",
                          [$stock, (float)($r['price'] ?? 0), $price, $r['primary_image_url'] ?? '', $r['primary_image_url'] ?? '', $ex['id']]);
                        $report['updated']++;
                    } else {
                        $title = trim(preg_replace('/(?i)\bcard bot\s*[-â€“:]?\s*/', '', (string)($r['title'] ?? '')));
                        if ($title === '' || preg_match('/grading|gift card|showbag|build your bundle/i', $title)) { $report['skipped']++; continue; }
                        $game = guess_game($title, (string)($r['product_type'] ?? ''), (string)($r['vendor'] ?? ''));
                        $section = guess_section($title, (string)($r['product_type'] ?? ''));
                        if ($game !== 'PokÃ©mon' && $game !== 'Accessories') $section = ['PSA Graded Cards' => 'Graded Cards', 'Booster Boxes' => 'Booster & Hobby Boxes', 'Booster Packs' => 'Packs', 'Booster Box Cases' => 'Cases', 'Premium & Special Sets' => 'Decks, Bundles & Sets', 'Elite Trainer Boxes' => 'Decks, Bundles & Sets'][$section] ?? $section;
                        $lang = preg_match('/japanese|jpkmn/i', $title . ($r['tags'] ?? '')) ? 'Japanese' : (preg_match('/chinese/i', $title) ? 'Chinese' : 'English');
                        $handle = slugify((string)($r['handle'] ?? $title));
                        if (one('SELECT 1 FROM products WHERE handle = ?', [$handle])) $handle .= '-' . substr(bin2hex(random_bytes(2)), 0, 4);
                        q("INSERT INTO products(source, source_id, handle, title, game, section, section_url, game_url, language, sku, price_usd, source_price, source_currency, in_stock, published, seo_index, image_url, alt_text, description)
                           VALUES('cardbot', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'AUD', ?, 1, ?, ?, ?, ?)",
                          [$sid, $handle, $title, $game, $section, section_url_for($game, $section), $game === 'PokÃ©mon' ? '/pokemon' : (one("SELECT path FROM collections WHERE kind='game' AND game=?", [$game])['path'] ?? ''),
                           $lang, (string)($r['sku'] ?? ''), $price, (float)($r['price'] ?? 0), $stock, ($section !== 'Single Cards' || ($price ?? 0) * $rate >= 15) ? 1 : 0, (string)($r['primary_image_url'] ?? ''), "$title, product photo",
                           '<p>' . h(strip_tags((string)($r['description'] ?? ''))) . '</p>']);
                        $id = (int)db()->lastInsertId();
                        sync_product_paths($id);
                        if ($np = one('SELECT * FROM products WHERE id = ?', [$id])) q('UPDATE products SET description = ? WHERE id = ?', [describe_product($np), $id]);
                        $report['created']++;
                        if (count($report['new']) < 200) $report['new'][] = [$id, $title, $game, $section];
                    }
                }
            }
            db()->commit();
        }
    }
    ob_start(); ?>
<h1>Import and export</h1>
<div class="cols">
  <section class="card"><h2>Import a CSV</h2>
    <p>Upload either file type. The site works out which one it is.</p>
    <ul class="small"><li><strong>Card Bot product export</strong> (the same columns as your <span class="mono">cardbot-products</span> file): updates stock and prices of products you already have, and adds new ones sorted into categories automatically.</li>
      <li><strong>Toramori export</strong> (from the Export button): the easy way to edit many products in Excel or Google Sheets and upload them back. Rows are matched by web address.</li></ul>
    <form method="post" enctype="multipart/form-data"><?= csrf_field() ?><label>CSV file<input type="file" name="csv" accept=".csv,text/csv" required></label><button class="btn primary">Import</button></form>
  </section>
  <section class="card"><h2>Export</h2><p>Download every product as a spreadsheet: prices, stock, categories, Google settings, descriptions.</p><a class="btn" href="/admin/export">Download products CSV</a>
    <p class="muted small">Prices in the CSV are USD. Card Bot imports convert AUD to USD at your AUD rate in Settings (now <?= h((string)(rates()['AUD'] ?? '')) ?> per USD).</p></section>
</div>
<?php if ($report): ?>
<section class="card"><h2>Import result</h2>
  <?php if (!empty($report['error'])): ?><p class="alert"><?= h($report['error']) ?></p><?php else: ?>
  <p><strong><?= $report['updated'] ?></strong> updated Â· <strong><?= $report['created'] ?></strong> added Â· <strong><?= $report['skipped'] ?></strong> skipped (<?= $report['mode'] === 'cardbot' ? 'Card Bot format' : 'Toramori format' ?>).</p>
  <?php if ($report['new']): ?><p class="small">New products were sorted automatically. Check their category, set and price:</p>
  <table class="tbl"><thead><tr><th>Product</th><th>Game</th><th>Category</th></tr></thead><tbody><?php foreach ($report['new'] as [$id, $t, $g, $s]): ?><tr><td><a href="/admin/products/edit?id=<?= $id ?>"><?= h($t) ?></a></td><td><?= h($g) ?></td><td><?= h($s) ?></td></tr><?php endforeach ?></tbody></table><?php endif ?>
  <?php endif ?>
</section>
<?php endif ?>
<?php echo admin_shell('Import and export', ob_get_clean(), 'import');
}

/* ------------------------------------------------------------------ orders */
function admin_orders(): void {
    $st = $_GET['status'] ?? '';
    $where = $st ? 'WHERE status = ?' : ''; $args = $st ? [$st] : [];
    $qq = trim((string)($_GET['q'] ?? ''));
    if ($qq !== '') { $where .= ($where ? ' AND' : 'WHERE') . ' (code LIKE ? OR name LIKE ? OR email LIKE ?)'; array_push($args, "%$qq%", "%$qq%", "%$qq%"); }
    $rows = all("SELECT o.*, (SELECT SUM(qty) FROM order_items WHERE order_id = o.id) units FROM orders o $where ORDER BY id DESC LIMIT 200", $args);
    ob_start(); ?>
<h1>Orders</h1>
<form class="filters card" method="get"><input type="search" name="q" value="<?= h($qq) ?>" placeholder="Order number, name or email" aria-label="Search orders">
  <select name="status" aria-label="Status"><option value="">All statuses</option><?= opt(['awaiting_payment' => 'Awaiting payment', 'paid' => 'Paid Â· to ship', 'shipped' => 'Shipped', 'cancelled' => 'Cancelled'], $st, true) ?></select><button class="btn">Show</button></form>
<div class="card flush"><table class="tbl"><thead><tr><th>Order</th><th>Customer</th><th>Units</th><th>Total</th><th>Payment</th><th>Status</th></tr></thead><tbody>
<?php if (!$rows): ?><tr><td colspan="6" class="muted">No orders here yet.</td></tr><?php endif ?>
<?php foreach ($rows as $o): $late = $o['status'] === 'awaiting_payment' && strtotime($o['hold_until']) < time(); ?>
<tr><td><a href="/admin/orders/view?id=<?= $o['id'] ?>"><strong><?= h($o['code']) ?></strong></a><div class="muted small"><?= h(date('j M Y, H:i', strtotime($o['created_at']))) ?></div></td>
<td><?= h($o['name']) ?><?= $o['company'] ? '<div class="muted small">' . h($o['company']) . '</div>' : '' ?><div class="muted small"><?= h($o['country']) ?></div></td>
<td class="mono"><?= (int)$o['units'] ?></td><td class="mono"><?= money((float)$o['total_usd'], 'USD') ?></td><td class="small"><?= h(PAYMENT_METHODS[$o['payment_method']][0] ?? $o['payment_method']) ?></td>
<td><?= status_pill($o['status']) ?><?= $late ? '<div class="small amber-text">Hold expired</div>' : '' ?></td></tr>
<?php endforeach ?></tbody></table></div>
<?php echo admin_shell('Orders', ob_get_clean(), 'orders');
}
function admin_order_view(): void {
    $o = one('SELECT * FROM orders WHERE id = ?', [(int)($_GET['id'] ?? 0)]);
    if (!$o) redirect('/admin/orders');
    if (is_post()) {
        $status = in_array($_POST['status'] ?? '', ['awaiting_payment', 'paid', 'shipped', 'cancelled'], true) ? $_POST['status'] : $o['status'];
        q("UPDATE orders SET status = ?, tracking = ?, admin_notes = ?, shipping_usd = ?, total_usd = subtotal_usd + COALESCE(?, 0), updated_at = datetime('now') WHERE id = ?",
          [$status, trim((string)$_POST['tracking']), trim((string)$_POST['admin_notes']), is_numeric($_POST['shipping_usd'] ?? null) ? (float)$_POST['shipping_usd'] : null, is_numeric($_POST['shipping_usd'] ?? null) ? (float)$_POST['shipping_usd'] : null, $o['id']]);
        if (!empty($_POST['notify'])) {
            $o2 = one('SELECT * FROM orders WHERE id = ?', [$o['id']]);
            $msg = ['awaiting_payment' => 'is waiting for payment.', 'paid' => 'is paid. We are preparing it for dispatch.', 'shipped' => 'has shipped.' . ($o2['tracking'] ? " Tracking: {$o2['tracking']}" : ''), 'cancelled' => 'has been cancelled.'][$status];
            send_mail($o2['email'], "Order {$o2['code']} update â€“ " . setting('site_name'), "Hello {$o2['name']},\n\nYour order {$o2['code']} $msg\n\nTotal: " . money((float)$o2['total_usd'], 'USD') . "\nOrder page: " . setting('site_url') . "/order/{$o2['code']}?k={$o2['token']}\n\n" . setting('site_name') . ' Â· ' . setting('support_email'));
        }
        flash('Order updated' . (!empty($_POST['notify']) ? ' and the customer was emailed.' : '.'));
        redirect('/admin/orders/view?id=' . $o['id']);
    }
    $items = all('SELECT * FROM order_items WHERE order_id = ?', [$o['id']]);
    ob_start(); ?>
<div class="head"><h1>Order <?= h($o['code']) ?> <?= status_pill($o['status']) ?></h1><a class="btn ghost" href="/order/<?= h($o['code']) ?>?k=<?= h($o['token']) ?>" target="_blank" rel="noopener">Customer's order page â†—</a></div>
<div class="edit-grid">
  <div>
    <section class="card flush"><table class="tbl"><thead><tr><th>Product</th><th>SKU</th><th>Qty</th><th>Unit</th><th>Total</th></tr></thead><tbody>
      <?php foreach ($items as $i): ?><tr><td><?= $i['product_id'] ? '<a href="/admin/products/edit?id=' . $i['product_id'] . '">' . h($i['title']) . '</a>' : h($i['title']) ?></td><td class="mono small"><?= h($i['sku']) ?></td><td class="mono"><?= (int)$i['qty'] ?></td><td class="mono"><?= money((float)$i['unit_usd'], 'USD') ?></td><td class="mono"><?= money((float)$i['line_usd'], 'USD') ?></td></tr><?php endforeach ?>
      <tr><td colspan="4">Subtotal</td><td class="mono"><?= money((float)$o['subtotal_usd'], 'USD') ?></td></tr>
      <tr><td colspan="4">Shipping (<?= h($o['shipping_method']) ?>)</td><td class="mono"><?= $o['shipping_usd'] === null ? 'Not set' : money((float)$o['shipping_usd'], 'USD') ?></td></tr>
      <tr><td colspan="4"><strong>Total</strong></td><td class="mono"><strong><?= money((float)$o['total_usd'], 'USD') ?></strong></td></tr>
    </tbody></table></section>
    <section class="card"><h2>Customer</h2>
      <p><strong><?= h($o['name']) ?></strong><?= $o['company'] ? ' Â· ' . h($o['company']) : '' ?><br><a href="mailto:<?= h($o['email']) ?>"><?= h($o['email']) ?></a><?= $o['phone'] ? ' Â· ' . h($o['phone']) : '' ?></p>
      <p><?= h($o['address1']) ?><?= $o['address2'] ? ', ' . h($o['address2']) : '' ?><br><?= h(trim("{$o['city']} {$o['region']} {$o['postcode']}")) ?><br><?= h($o['country']) ?></p>
      <p class="small muted">Payment: <?= h(PAYMENT_METHODS[$o['payment_method']][0] ?? $o['payment_method']) ?><?= $o['payment_method'] === 'bitcoin' && $o['btc_amount'] ? ' Â· ' . h($o['btc_amount']) . ' BTC expected' : ($o['payment_method'] !== 'bitcoin' ? ' Â· send payment details by email or text within 12 hours' : '') ?><?= $o['weight_kg'] ? ' Â· ' . number_format((float)$o['weight_kg'], 1) . ' kg' : '' ?> Â· Shown in <?= h($o['currency']) ?> Â· Stock held until <?= h(date('j M, H:i', strtotime($o['hold_until']))) ?> UTC</p>
      <?php if ($o['notes']): ?><p><strong>Customer note:</strong> <?= nl2br(h($o['notes'])) ?></p><?php endif ?>
    </section>
  </div>
  <form method="post" class="card"><?= csrf_field() ?><h2>Update</h2>
    <label>Status<select name="status"><?= opt(['awaiting_payment' => 'Awaiting payment', 'paid' => 'Paid Â· to ship', 'shipped' => 'Shipped', 'cancelled' => 'Cancelled'], $o['status'], true) ?></select></label>
    <label>Shipping charge (USD) <span class="muted">sets the invoice total</span><input type="number" step="0.01" min="0" name="shipping_usd" value="<?= h((string)$o['shipping_usd']) ?>"></label>
    <label>Tracking number<input name="tracking" value="<?= h($o['tracking']) ?>"></label>
    <label>Private notes<textarea name="admin_notes" rows="4"><?= h($o['admin_notes']) ?></textarea></label>
    <label class="inline"><input type="checkbox" name="notify" value="1"> Email the customer about this update</label>
    <button class="btn primary">Save</button>
  </form>
</div>
<?php echo admin_shell('Order ' . $o['code'], ob_get_clean(), 'orders');
}

