  <tr><td><a href="/admin/pages/edit?path=<?= h(urlencode($pg['path'])) ?>"><?= h($pg['h1'] ?: $pg['title']) ?></a><div class="muted small mono"><?= h($pg['path']) ?></div></td><td class="small"><?= h(ucfirst($pg['type'])) ?></td><td class="small"><?= h($pg['primary_kw'] ?: 'â€”') ?></td>
  <td><?= $pg['published'] ? '<span class="status green">Live</span>' : '<span class="status grey">Draft</span>' ?><?= $ph ? ' <span class="status amber">Needs writing</span>' : '' ?></td><td class="small muted"><?= h(date('j M Y', strtotime($pg['updated_at']))) ?></td></tr>
