  <label>Description in Google <span class="muted" data-count-for="meta_desc"></span><textarea name="meta_desc" rows="3" data-count="155"><?= h($r['meta_desc'] ?? '') ?></textarea></label>
  <label class="inline"><input type="checkbox" name="seo_index" <?= ($r['seo_index'] ?? 1) ? 'checked' : '' ?>> Show in Google</label>
  <div class="serp"><div class="serp-url"><?= h(setting('site_url') . ($r['path'] ?? '')) ?></div><div class="serp-title" data-serp-title><?= h(($r['seo_title'] ?? '') ?: $placeholderTitle) ?></div><div class="serp-desc" data-serp-desc><?= h($r['meta_desc'] ?? '') ?></div></div>
