function view_checkout(array $__vars): void { extract($__vars, EXTR_SKIP); ?><?php
$min = (float)setting('min_order_usd');
$kg = cart_weight($s['lines']); $country = $d['country'] ?? 'United States';
$std = shipping_cost($s['subtotal'], 'standard', $country, $kg); $exp = shipping_cost($s['subtotal'], 'express', $country, $kg);
