/* Toramori storefront */
(() => {
  const $ = (s, el = document) => el.querySelector(s);
  const $$ = (s, el = document) => [...el.querySelectorAll(s)];
  const PK = window.PK || {};
  const fmt = usd => {
    const v = usd * (PK.rate || 1);
    return (PK.sym || '$') + (PK.cur === 'JPY' ? Math.round(v).toLocaleString('en-US') : v.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2}));
  };
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));

  async function api(url, body) {
    const opt = body ? {method: 'POST', headers: {'Content-Type': 'application/json', 'X-CSRF': PK.csrf}, body: JSON.stringify(body)} : {};
    const r = await fetch((url.startsWith('/') ? PK.base || '' : '') + url, opt);
    if (!r.ok) throw new Error('Request failed');
    return r.json();
  }
  let toastT;
  function toast(html) {
    const t = $('.toast'); t.innerHTML = html; t.hidden = false;
    clearTimeout(toastT); toastT = setTimeout(() => (t.hidden = true), 3500);
  }
  function setCount(n) { $$('[data-cart-count]').forEach(b => (b.textContent = n)); }

  /* ---------- dropdown menus */
  const items = $$('[data-menu]');
  const closeAll = except => items.forEach(it => { if (it !== except) { const b = $('.nav-btn', it); b.setAttribute('aria-expanded', 'false'); $('.panel', it).hidden = true; } });
  const desktop = () => window.matchMedia('(min-width: 1021px)').matches;
  items.forEach(it => {
    const btn = $('.nav-btn', it), panel = $('.panel', it);
    const open = () => { closeAll(it); btn.setAttribute('aria-expanded', 'true'); panel.hidden = false; };
    btn.addEventListener('click', () => (btn.getAttribute('aria-expanded') === 'true' ? (btn.setAttribute('aria-expanded', 'false'), (panel.hidden = true)) : open()));
    it.addEventListener('mouseenter', () => desktop() && open());
    it.addEventListener('mouseleave', () => desktop() && closeAll());
  });
  document.addEventListener('keydown', e => { if (e.key === 'Escape') { closeAll(); closeDrawer(); } });
  document.addEventListener('click', e => { if (desktop() && !e.target.closest('[data-menu]')) closeAll(); });
  const mb = $('[data-mobile-menu]');
  if (mb) mb.addEventListener('click', () => { const nav = $('.nav'); const on = nav.classList.toggle('open'); if (on) { window.scrollTo(0, 0); nav.style.top = Math.round($('.hdr').getBoundingClientRect().bottom) + 'px'; } mb.setAttribute('aria-expanded', on); document.body.style.overflow = on ? 'hidden' : ''; });

  /* ---------- quantity steppers */
  function clampQty(form, v) {
    const step = +form.dataset.step || 1, moq = +form.dataset.moq || 1, min = form.hasAttribute('data-set') ? 0 : moq;
    v = Math.max(min, Math.round(v) || 0);
    if (v > 0 && v < moq) v = moq;
    if (v > moq && (v - moq) % step) v += step - ((v - moq) % step);
    return v;
  }
  document.addEventListener('click', e => {
    const b = e.target.closest('[data-dec],[data-inc]');
    if (!b) return;
    const form = b.closest('form'), inp = $('input[name=qty]', form);
    const step = +form.dataset.step || 1, moq = +form.dataset.moq || 1;
    let v = +inp.value || 0;
    if (b.hasAttribute('data-inc')) v = v < moq ? moq : v + step;
    else v = v - step < moq ? (form.hasAttribute('data-set') ? 0 : moq) : v - step;
    inp.value = clampQty(form, v);
    inp.dispatchEvent(new Event('change', {bubbles: true}));
  });
  document.addEventListener('change', e => {
    if (e.target.name === 'qty' && e.target.closest('[data-add],[data-set]')) {
      const form = e.target.closest('form');
      e.target.value = clampQty(form, +e.target.value);
      if (form.hasAttribute('data-pdp')) updatePdp(+e.target.value);
      if (form.hasAttribute('data-set')) setLine(form);
    }
  });

  /* ---------- add to order */
  document.addEventListener('submit', async e => {
    const form = e.target.closest('[data-add]');
    if (!form) return;
    e.preventDefault();
    const inp = $('input[name=qty]', form);
    const qty = clampQty(form, +inp.value);
    const btn = $('button[type=submit]', form); btn.disabled = true;
    try {
      const c = await api('/api/cart', {action: 'add', id: +form.dataset.id, qty});
      setCount(c.count);
      const line = c.lines.find(l => l.id === +form.dataset.id);
      toast(`Added ${qty} Ã— ${esc(line ? line.title : 'item')}. <a href="${PK.base || ''}/cart">View order (${c.count})</a>`);
      renderDrawer(c);
    } catch { toast('Could not add that item. Refresh the page and try again.'); }
    btn.disabled = false;
  });

  /* ---------- product page live pricing */
  function updatePdp(q) {
    const t = $('[data-ladder]'); const unitEl = $('[data-unit]'); const totalEl = $('[data-total]');
    let tiers = t ? JSON.parse(t.dataset.ladder) : null;
    const form = $('[data-pdp]');
    if (!tiers) { const u = unitEl ? parseFloat(unitEl.dataset.usd || 0) : 0; return; }
    let idx = 0; tiers.forEach((tr, i) => { if (q >= tr[0]) idx = i; });
    $$('tbody tr', t).forEach((r, i) => r.classList.toggle('is-active', i === idx));
    unitEl.textContent = tiers[idx][2];
    $('[data-qty-label]').textContent = q;
    totalEl.textContent = fmt(tiers[idx][1] * q / (PK.rate ? 1 : 1));
    const nudge = $('[data-nudge]'), next = tiers[idx + 1];
    if (nudge) { nudge.hidden = !next; if (next) nudge.textContent = `${next[0] - q} more and each unit drops to ${next[2]}.`; }
  }
  const pdpQty = $('[data-pdp] input[name=qty]');
  if (pdpQty && !$('[data-ladder]')) {
    // single-price products: keep the total in step with quantity
    const unitTxt = $('[data-unit]'), total = $('[data-total]');
    const base = parseFloat((total?.textContent || '').replace(/[^0-9.]/g, '')) / (+pdpQty.value || 1);
    pdpQty.addEventListener('change', () => { if (total) total.textContent = (PK.sym || '$') + (base * +pdpQty.value).toLocaleString('en-US', {minimumFractionDigits: PK.cur === 'JPY' ? 0 : 2, maximumFractionDigits: PK.cur === 'JPY' ? 0 : 2}); $('[data-qty-label]').textContent = pdpQty.value; });
  }

